contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}
    function run(address receiver, uint amount) public payable {
        // msg.sender of calls on c is this contract, which deployed c, so owner == this
        // and any sendTo from here is from the owner; to test a non-owner we must observe
        // the owner-only guard from a different angle: the call must revert when it would
        // fail. Instead, use the accepted owner rule's complement is inaccessible, so test
        // revert on insufficient balance: owner calling with amount > balance reverts.
        require(receiver != address(this));
        uint bal = address(c).balance;
        bool reverted;
        c.sendTo(receiver, bal + 1); bool __rev0 = __ESBMC_reverted(); if (__rev0) { reverted = true; } else { reverted = false; }
        assert(reverted && address(c).balance == bal);
    }
    receive() external payable {}
}

